@Test
public void testMomentsSampling() {
    final UniformRandomProvider rng = RandomSource.create(RandomSource.WELL_1024_A, 123456789L);
    final int numSamples = 1000;
    for (final double alpha : alphaBetas) {
        for (final double beta : alphaBetas) {
            final BetaDistribution betaDistribution = new BetaDistribution(alpha, beta);
            final double[] observed = AbstractContinuousDistribution.sample(numSamples, betaDistribution.createSampler(rng));
            Arrays.sort(observed);
            final String distribution = String.format("Beta(%.2f, %.2f)", alpha, beta);
            Assert.assertEquals(String.format("E[%s]", distribution), betaDistribution.getMean(), StatUtils.mean(observed), epsilon);
            Assert.assertEquals(String.format("Var[%s]", distribution), betaDistribution.getVariance(), StatUtils.variance(observed), epsilon);
        }
    }
}

@Test
public void testGoodnessOfFit() {
    final UniformRandomProvider rng = RandomSource.create(RandomSource.WELL_19937_A, 123456789L);
    final int numSamples = 1000;
    final double level = 0.01;
    for (final double alpha : alphaBetas) {
        for (final double beta : alphaBetas) {
            final BetaDistribution betaDistribution = new BetaDistribution(alpha, beta);
            final ContinuousDistribution.Sampler sampler = betaDistribution.createSampler(rng);
            final double[] observed = AbstractContinuousDistribution.sample(numSamples, sampler);
            final double gT = gTest(betaDistribution, observed);
            Assert.assertFalse("G goodness-of-fit (" + gT + ") test rejected null at alpha = " + level, gT < level);
        }
    }
}

