/**
 * Verify that density integrals match the distribution.
 * The (filtered, sorted) cumulativeTestPoints array is used to source
 * integration limits. The integral of the density (estimated using a
 * Legendre-Gauss integrator) is compared with the cdf over the same
 * interval. Test points outside of the domain of the density function
 * are discarded.
 */
@Test
public void testDensityIntegrals() {
    final double tol = 1e-9;
    final BaseAbstractUnivariateIntegrator integrator = new IterativeLegendreGaussIntegrator(5, 1e-12, 1e-10);
    final UnivariateFunction d = new UnivariateFunction() {

        @Override
        public double value(double x) {
            return distribution.density(x);
        }
    };
    final ArrayList<Double> integrationTestPoints = new ArrayList<>();
    for (int i = 0; i < cumulativeTestPoints.length; i++) {
        if (Double.isNaN(cumulativeTestValues[i]) || cumulativeTestValues[i] < 1e-5 || cumulativeTestValues[i] > 1 - 1e-5) {
            // exclude integrals outside domain.
            continue;
        }
        integrationTestPoints.add(cumulativeTestPoints[i]);
    }
    Collections.sort(integrationTestPoints);
    for (int i = 1; i < integrationTestPoints.size(); i++) {
        Assert.assertEquals(distribution.probability(integrationTestPoints.get(0), integrationTestPoints.get(i)), // Triangle integrals are very slow to converge
        integrator.// Triangle integrals are very slow to converge
        integrate(// Triangle integrals are very slow to converge
        1000000, d, integrationTestPoints.get(0), integrationTestPoints.get(i)), tol);
    }
}

